CREATE FUNCTION public.verify_test_assert(ok boolean,message text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL: %',message; END IF; RAISE NOTICE 'PASS: %',message; END $$;
CREATE FUNCTION public.verify_test_reject(statement text,message text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN BEGIN EXECUTE statement; EXCEPTION WHEN OTHERS THEN RAISE NOTICE 'PASS: %',message; RETURN; END; RAISE EXCEPTION 'FAIL: expected rejection: %',message; END $$;
CREATE FUNCTION public.verify_test_cannot_remove(path text) RETURNS boolean LANGUAGE plpgsql AS $$
DECLARE removed integer;
BEGIN
 WITH deleted AS (DELETE FROM storage.objects WHERE bucket_id='provider-credentials' AND name=path RETURNING id) SELECT count(*) INTO removed FROM deleted;
 RETURN removed=0;
EXCEPTION WHEN insufficient_privilege THEN RETURN true;
END $$;
